"""Guía de cada pieza según su papel mecánico en el sistema (el "puesto" del dibujo), explicada como lo haría un mecánico.

Sirve para cualquier catálogo (inglés o español): la pieza ya está ubicada en su puesto del dibujo, así que sabemos qué
es aunque el catálogo la llame raro. Clave: "diagrama:puesto" (cuando la misma pieza cumple otro papel en otro sistema)
o solo "puesto". Cada entrada: qué hace, cada cuánto, señales, cómo revisarla, qué pasa si no se atiende, consejos.
"""
import re

from .despiece_fichas import DIFICULTAD


def _g(que_hace, cada_cuanto, senales, como_revisar, si_no, tips, dificultad="taller"):
    return {"que_hace": que_hace, "cada_cuanto": cada_cuanto, "senales": senales, "como_revisar": como_revisar,
            "si_no": si_no, "tips": tips, "dificultad": dificultad, "dificultad_texto": DIFICULTAD[dificultad]}


