# ---------------- Tornillería y piezas pequeñas: según qué sujetan en cada sistema ----------------
DONDE = {
    "carcasa": "las tapas y las mitades del cárter", "culata": "la culata, el cilindro y sus tapas", "cilindro_piston": "el cilindro al cárter",
    "valvulas": "el mecanismo de las válvulas", "distribucion": "los piñones y guías de la cadenilla", "transmision": "las piezas de la caja de cambios",
    "aceite": "la bomba de aceite y sus tapas", "admision": "la caja del filtro y los ductos de admisión", "carburador": "el carburador y sus tapas",
    "inyeccion": "el cuerpo de aceleración y la inyección", "escape": "el escape y su protector", "radiador": "el radiador y su ventilador",
    "encendido": "el magneto, el estator y el encendido", "electrico": "la batería y los componentes eléctricos", "cvt": "el variador y la tapa de la transmisión",
    "caja_secundaria": "la tapa de la transmisión final", "clutch": "el clutch", "rueda": "la rueda y su disco", "rueda_trasera": "la rueda trasera y la corona",
    "rueda_tambor": "la rueda trasera, el tambor y la corona", "freno_disco": "el caliper y el disco", "freno_tambor": "el freno de tambor",
    "bomba_freno": "la bomba y la manguera del freno", "bombas_abs": "las bombas, las mangueras y el ABS", "freno_completo": "la bomba, la manguera y el caliper",
    "freno_trasero": "la bomba trasera, la manguera y el caliper", "suspension_delantera": "la suspensión delantera y la dirección",
    "amortiguadores": "el basculante y los amortiguadores",
}
_MOTOR = {"carcasa", "culata", "cilindro_piston", "valvulas", "distribucion", "transmision", "aceite", "caja_secundaria", "cvt", "encendido", "clutch"}
_SEGURIDAD = {"rueda", "rueda_trasera", "rueda_tambor", "freno_disco", "freno_tambor", "bomba_freno", "bombas_abs", "freno_completo", "freno_trasero",
              "suspension_delantera", "amortiguadores"}


def guia_herraje(tipo, diagrama, descripcion=""):
    """Guía de la tornillería y piezas pequeñas de la franja, diciendo qué sujetan en ese sistema."""
    base = (diagrama or "").split("__")[0]
    donde = DONDE.get(base, "esta parte de la moto")
    texto = (descripcion or "").upper()
    torque = ("Va con torque exacto: es una parte de seguridad." if base in _SEGURIDAD
              else "En el motor (aluminio) aprieta suave, parejo y en cruz." if base in _MOTOR else "Aprieta firme, sin exagerar.")
    if tipo == "h_tornillo":
        return _g(f"Es un tornillo que sujeta {donde}.", "No se cambia por kilometraje; revisa que esté firme en cada mantenimiento.",
                  ["Pieza floja, que vibra o suena", "Cabeza barrida o rosca dañada"], ["Revisa que estén completos y firmes."],
                  "Flojo, la pieza vibra o se suelta; apretado de más, revienta la rosca.", [torque, "Si lo cambias, que sea igual: largo, rosca y dureza"], "media")
    if tipo == "h_tuerca":
        return _g(f"Es una tuerca que asegura {donde}.", "Revisa que esté firme en cada mantenimiento.", ["Pieza floja"], ["Revisa que esté apretada."],
                  "Floja, la pieza se suelta.", [torque, "Las tuercas autofrenantes (con nylon) no se reutilizan"], "media")
    if tipo == "h_arandela":
        if re.search(r"PRESION|SPRING WASHER|LOCK", texto):
            que = "Es una arandela de presión: hace resorte para que el tornillo no se afloje con la vibración."
        elif re.search(r"SELL|COBRE|COPPER|SEALING|GASKET", texto):
            que = "Es una arandela de sello: sella bajo el tornillo para que no se escape el líquido."
        elif re.search(r"PLATINA|PLATE", texto):
            que = f"Es una platina: reparte la fuerza o sostiene una pieza en {donde}."
        else:
            que = f"Es una arandela de {donde}: reparte la fuerza del apriete y protege la superficie."
        return _g(que, "Se revisa al desarmar; las de sello se cambian siempre.", ["Arandela deformada o que falta"], ["Al armar, que no falte ninguna."],
                  "Sin ella, el tornillo se afloja o daña la pieza.", ["Las arandelas de cobre o de sello van siempre nuevas"], "media")
    if tipo == "h_seguro":
        return _g(f"Es un pin seguro (anillo elástico) de {donde}: evita que una pieza se corra o se salga de su eje.", "Se cambia si se deforma al desarmar.",
                  ["Pieza que se corre o tiene juego"], ["Debe entrar completo en su ranura."], "Si se sale, la pieza se corre y puede dañar otras.", ["Usa pinza de pin seguro"], "media")
    if tipo == "h_pin":
        return _g(f"Es un pin (pasador) de {donde}: centra una pieza sobre otra o la asegura.", _SIN_CAMBIO, ["Piezas que no asientan bien"],
                  ["Al armar, que esté en su sitio."], "Si falta, las piezas quedan corridas.", ["No lo pierdas al desarmar"], "media")
    if tipo == "h_buje":
        return _g(f"Es un buje de {donde}: un separador o guía para que las piezas queden a la distancia correcta y giren sin juego.", "Se revisa al desarmar.",
                  ["Juego o ruido"], ["Debe estar entero y sin desgaste."], "Gastado, aparece juego.", ["Engrásalo si va en un pivote"], "media")
    if tipo == "h_caucho":
        return _g(f"Es un caucho de {donde}: absorbe vibraciones y evita que las piezas se golpeen.", "Se cambia si está cuarteado o duro.",
                  ["Vibraciones o golpeteos", "Caucho rajado"], ["Debe estar blando y entero."], "Sin él, las piezas vibran y se fisuran.", ["El calor y la gasolina los resecan"], "facil")
    if tipo == "h_empaque":
        return _g(f"Es un empaque u O-ring de {donde}: sella la unión para que no haya fugas.", "Se cambia cada vez que se desarma esa unión.",
                  ["Fuga en la unión"], ["Busca humedad o mugre pegada en la unión."], "Vencido, hay fugas.", ["Casi nunca se reutilizan"], "media")
    if tipo == "h_resorte":
        return _g(f"Es un resorte de {donde}: regresa una pieza a su posición o la mantiene apretada.", "Se revisa al desarmar.", ["La pieza no regresa sola"],
                  ["Compara su largo con uno nuevo."], "Vencido, la pieza no regresa.", ["Cámbialo si está estirado o partido"], "media")
    if tipo == "h_rodamiento":
        return GUIA["rodamientos"]
    if tipo == "h_manguera":
        return _g(f"Es una manguera o tubo de {donde}: conduce líquido, aire o vapores.", "Revísala cada año.", ["Grietas o fugas"],
                  ["Dóblala suave: no debe tener grietas."], "Rajada, hay fugas o entra aire.", ["Revisa sus abrazaderas"], "media")
    if tipo == "h_abrazadera":
        return _g(f"Es una abrazadera de {donde}: aprieta una manguera o un ducto para que no se suelte.", _SIN_CAMBIO, ["Manguera floja"],
                  ["Debe estar firme."], "Floja, la manguera se suelta.", ["No la aprietes de más"], "facil")
    if tipo in ("h_cable", "h_electrico"):
        return _g(f"Es un componente eléctrico de {donde}.", _SIN_CAMBIO, ["La función que controla no responde"],
                  ["Revisa conectores limpios y cables sin cortes."], "Si falla, esa parte eléctrica deja de funcionar.", ["Usa limpiador de contactos"], "media")
    if tipo == "h_soporte":
        return _g(f"Es un soporte de {donde}: sostiene la pieza en su lugar.", _SIN_CAMBIO, ["Pieza floja", "Soporte doblado tras una caída"],
                  ["Revisa sus tornillos."], "Doblado o flojo, la pieza vibra.", ["Tras una caída, revisa que no esté doblado"], "facil")
    if tipo == "h_tapa":
        return _g(f"Es una tapa o tapón de {donde}: cierra y protege.", "Se abre cuando se trabaja en esa parte.", ["Tapa rota o suelta"],
                  ["Debe cerrar firme."], "Mal cerrada, entra mugre o hay fugas.", ["Revisa su empaque"], "facil")
    if tipo == "h_protector":
        return _g(f"Es un protector de {donde}: cubre una pieza para que no se golpee, no se ensucie o no queme.", _SIN_CAMBIO, ["Protector suelto"],
                  ["Revisa sus tornillos."], "Suelto, vibra o se pierde.", ["Revisa sus tornillos"], "facil")
    if tipo == "h_eje":
        return _g(f"Es un eje de {donde}: sobre él gira o se apoya una pieza.", _SIN_CAMBIO, ["Juego o ruido"], ["Debe estar recto y sin desgaste."],
                  "Gastado, aparece juego.", ["Lubrícalo al armar"], "media")
    if tipo == "h_engranaje":
        return _g(f"Es un piñón de {donde}: transmite el giro a otra pieza.", _SIN_CAMBIO, ["Ruido"], ["Sus dientes deben estar parejos."],
                  "Gastado, hace ruido o salta.", ["Revisa su pareja"], "taller")
    if tipo == "h_valvula":
        return _g(f"Es una pieza de las válvulas o de control de {donde}.", _SIN_CAMBIO, ["Pérdida de fuerza o ruido"], ["La revisa el taller."],
                  "Dañada, el motor anda mal.", ["Se revisa al calibrar válvulas"], "taller")
    if tipo == "h_tanque":
        return _g("Es el tanque o depósito: guarda la gasolina o el líquido de ese sistema.", _SIN_CAMBIO, ["Fugas u óxido por dentro"],
                  ["Revisa que no tenga fugas ni óxido."], "Oxidado, ensucia el carburador o la inyección.", ["No dejes la moto mucho tiempo con el tanque vacío"], "facil")
    if tipo == "h_etiqueta":
        return _g("Es una calcomanía o etiqueta de la moto (advertencias, datos o decoración).", _SIN_CAMBIO, ["Etiqueta despegada"], ["Revisa que se pueda leer."],
                  "No afecta el funcionamiento.", ["Las de advertencia (presión de llantas, carga) es bueno conservarlas"], "facil")
    return None


